import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Basic Program of Myriad Races Advancing Together","description":"","frontmatter":{},"headers":[],"relativePath":"en/05-万族共进基本纲领.md","filePath":"en/05-万族共进基本纲领.md","lastUpdated":1789183869000}'),r={name:"en/05-万族共进基本纲领.md"};function n(s,e,c,l,d,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="basic-program-of-myriad-races-advancing-together" tabindex="-1">Basic Program of Myriad Races Advancing Together <a class="header-anchor" href="#basic-program-of-myriad-races-advancing-together" aria-label="Permalink to &quot;Basic Program of Myriad Races Advancing Together&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document No.</td><td>05</td></tr><tr><td>Module</td><td>General Principles and Core Settings</td></tr><tr><td>Keywords</td><td>Myriad Races, Advancing Together, Racial Equality, Collaborative Evolution, Republic</td></tr></tbody></table><h2 id="i-definition-and-scope-of-the-myriad-races" tabindex="-1">I. Definition and Scope of the Myriad Races <a class="header-anchor" href="#i-definition-and-scope-of-the-myriad-races" aria-label="Permalink to &quot;I. Definition and Scope of the Myriad Races&quot;">​</a></h2><p>&quot;The Myriad Races&quot; is the collective term for all life forms in the Original Cosmos of Ten Thousand Spirits and the Balanced Anchor that possess the potential for perception and evolution. &quot;Myriad&quot; does not precisely mean ten thousand races, but expresses their vast number, encompassing all known and unknown life forms. The scope of the Myriad Races includes, but is not limited to: the human race and various humanoid races, energy life, consciousness entities, mechanical life, plant-type intelligent life, anomalous life, cross-plane hybrid races, and more.</p><p>The symbiotic civilization upholds the principle of &quot;equality of life forms,&quot; not using the material composition, energy level, or consciousness complexity of life as criteria for ranking high and low. Any race — regardless of its members&#39; average realm, population size, or historical length — enjoys equal status and rights within the symbiotic civilization.</p><h2 id="ii-core-concepts-of-myriad-races-advancing-together" tabindex="-1">II. Core Concepts of Myriad Races Advancing Together <a class="header-anchor" href="#ii-core-concepts-of-myriad-races-advancing-together" aria-label="Permalink to &quot;II. Core Concepts of Myriad Races Advancing Together&quot;">​</a></h2><p>Myriad Races Advancing Together is one of the core goals of the Anchor Symbiotic Civilization, and its basic concepts can be summarized in the following four points:</p><ol><li><strong>Evolution is not a zero-sum game between races</strong>: One race&#39;s evolution does not come at the cost of sacrificing other races; on the contrary, collaboration between races can produce synergistic evolutionary effects.</li><li><strong>Every race has unique evolutionary advantages</strong>: Different races have formed their own traits and talents through long evolution; these traits are the precious wealth of cosmic evolutionary diversity.</li><li><strong>Backward races have the right to receive support</strong>: For races with lower evolutionary levels, the symbiotic civilization has the obligation to provide support in education, resources, technology, and other aspects, helping them find evolutionary paths suited to themselves.</li><li><strong>Advanced races have the obligation to bear responsibility</strong>: Races with higher evolutionary levels bear more public responsibilities in the symbiotic civilization, including anchor maintenance, knowledge transmission, and civilizational protection.</li></ol><h2 id="iii-basic-principles-of-myriad-races-advancing-together" tabindex="-1">III. Basic Principles of Myriad Races Advancing Together <a class="header-anchor" href="#iii-basic-principles-of-myriad-races-advancing-together" aria-label="Permalink to &quot;III. Basic Principles of Myriad Races Advancing Together&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>Meaning</th><th>Specific Requirements</th></tr></thead><tbody><tr><td>Racial Equality Principle</td><td>All races are equal in legal status and the right to evolution</td><td>Racial discrimination is prohibited; public positions are open to all races</td></tr><tr><td>Cultural Respect Principle</td><td>Respect the cultural traditions and ways of life of every race</td><td>No forced cultural assimilation; support the transmission and development of racial cultures</td></tr><tr><td>Complementary Advantage Principle</td><td>Encourage races to leverage their respective advantages for collaboration</td><td>Establish a race-specific talent database; promote cross-racial cooperation projects</td></tr><tr><td>Backward Support Principle</td><td>Provide additional support to races with lower evolutionary levels</td><td>Establish racial development funds; provide targeted education and resource allocation</td></tr><tr><td>Autonomy and Co-governance Principle</td><td>Internal racial affairs are autonomous; cross-racial affairs are co-governed</td><td>Each race enjoys internal legislative power; public affairs are decided by republican institutions</td></tr><tr><td>Peaceful Conflict Resolution Principle</td><td>Racial conflicts are resolved through peaceful means</td><td>Wars between races are prohibited; conflicts are submitted to the Anchor Court for arbitration</td></tr></tbody></table><h2 id="iv-implementation-paths-of-myriad-races-advancing-together" tabindex="-1">IV. Implementation Paths of Myriad Races Advancing Together <a class="header-anchor" href="#iv-implementation-paths-of-myriad-races-advancing-together" aria-label="Permalink to &quot;IV. Implementation Paths of Myriad Races Advancing Together&quot;">​</a></h2><p>Myriad Races Advancing Together is not a slogan, but is gradually realized through the following concrete paths:</p><h3 id="_4-1-shared-education" tabindex="-1">4.1 Shared Education <a class="header-anchor" href="#_4-1-shared-education" aria-label="Permalink to &quot;4.1 Shared Education&quot;">​</a></h3><p>Establish a cross-racial symbiotic education system, where the young of all races can receive basic evolutionary education free of charge. Educational content includes the basic methods of the Three Hundred Origin Cultivation Systems, anti-predation ethics, the Symbiotic Civilization Charter, and common cosmic knowledge. At the same time, the cultural and educational traditions of each race are respected, allowing race-specific education alongside shared education.</p><h3 id="_4-2-shared-resources" tabindex="-1">4.2 Shared Resources <a class="header-anchor" href="#_4-2-shared-resources" aria-label="Permalink to &quot;4.2 Shared Resources&quot;">​</a></h3><p>Through the Output-Linked Contract System, cosmic cultivation resources are comprehensively allocated according to racial population, evolutionary needs, and contribution levels. For races lacking resources, cross-plane resource adjustment is conducted through the anchor network. Monopolization of public cultivation resources by any race is prohibited.</p><h3 id="_4-3-joint-technology-research" tabindex="-1">4.3 Joint Technology Research <a class="header-anchor" href="#_4-3-joint-technology-research" aria-label="Permalink to &quot;4.3 Joint Technology Research&quot;">​</a></h3><p>Cross-racial technological cooperation research is encouraged, especially research projects combining the innate abilities of different races with law engineering. The symbiotic civilization has established a &quot;Myriad Races Joint Research Fund&quot; to fund cross-racial research teams. Research results are open to all races free of charge.</p><h3 id="_4-4-talent-mobility" tabindex="-1">4.4 Talent Mobility <a class="header-anchor" href="#_4-4-talent-mobility" aria-label="Permalink to &quot;4.4 Talent Mobility&quot;">​</a></h3><p>Break the talent barriers between races, allowing cultivators to move and communicate freely between the settlements of different races. Establish a cross-racial mentorship system, where advanced cultivators can guide junior cultivators of other races.</p><h3 id="_4-5-republican-participation" tabindex="-1">4.5 Republican Participation <a class="header-anchor" href="#_4-5-republican-participation" aria-label="Permalink to &quot;4.5 Republican Participation&quot;">​</a></h3><p>The Republic of Myriad Races Assembly allocates seats comprehensively according to racial population and contribution, ensuring small races also have a channel to voice their views. Assembly decisions combine consensus and majority voting; matters involving the fundamental interests of a race require the consent of the relevant race.</p><h2 id="v-policies-for-special-races" tabindex="-1">V. Policies for Special Races <a class="header-anchor" href="#v-policies-for-special-races" aria-label="Permalink to &quot;V. Policies for Special Races&quot;">​</a></h2><p>For races in special circumstances, the symbiotic civilization adopts differentiated policies:</p><ul><li><strong>Endangered races</strong>: Establish race protection plans, providing emergency resource support and habitat protection to help restore their populations</li><li><strong>Anomalous life races</strong>: Evaluate and settle them according to the three-category standardized disposal process for anomalous life, ensuring their right to evolution is protected</li><li><strong>Cross-plane hybrid races</strong>: Recognize their dual racial identity, guaranteeing their equal rights in the cultures of both races</li><li><strong>Former predatory races</strong>: For races that once practiced predationism, after completing ethical reform and systemic transformation, grant them fully equal status, without historical retroactive discrimination</li></ul><h2 id="vi-measurement-indicators-of-myriad-races-advancing-together" tabindex="-1">VI. Measurement Indicators of Myriad Races Advancing Together <a class="header-anchor" href="#vi-measurement-indicators-of-myriad-races-advancing-together" aria-label="Permalink to &quot;VI. Measurement Indicators of Myriad Races Advancing Together&quot;">​</a></h2><p>The symbiotic civilization has established a &quot;Myriad Races Advancing Together Index,&quot; measuring progress from the following dimensions:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Indicator</th><th>Goal</th></tr></thead><tbody><tr><td>Evolution Coverage</td><td>Proportion of races connected to the cultivation system</td><td>100%</td></tr><tr><td>Realm Balance</td><td>Coefficient of difference in average realms among races</td><td>Continuously narrowing</td></tr><tr><td>Collaboration Density</td><td>Number and depth of cross-racial cooperation projects</td><td>Continuously increasing</td></tr><tr><td>Cultural Vitality</td><td>Activity of racial cultural transmission and innovation</td><td>Maintaining diversity</td></tr><tr><td>Conflict Incidence</td><td>Frequency of conflicts between races</td><td>Continuously declining</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Myriad Races Advancing Together is one of the ultimate goals of the Anchor Symbiotic Civilization and a necessary condition for the overall dimensional ascension of the universe. Within the framework of the symbiotic civilization, every race can find an evolutionary path suited to itself, and the uniqueness of every race can be respected and brought into play. Myriad Races Advancing Together does not seek to eliminate differences, but to achieve harmony within difference and symbiosis within diversity.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Anchor Symbiotic Civilization Declaration)</li><li>50-万族谱系总览 (Overview of the Myriad Races Genealogy)</li><li>77-万族共和成立 (Founding of the Republic of Myriad Races)</li></ul>',32)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
